def build_pipeline(checkpointer, runtime):
    """The graph over the runtime's plan: `launch_<lane>` and `verify_<lane>` per selected lane, then the fixed tail."""
    workers = list(runtime.workers)
    def launcher(node):
        return lambda _state: {"lanes": {node: runtime.launch(node)}}
    def verifier(node):
        return lambda state: {"packets": {node: runtime.verify(node, state["snapshots"])}}
    def handoff(_state):
        message = ("Awaiting explicit completion signals and automatic freeze." if runtime.plan.get("automatic")
                   else f"Type in Claude terminals; provide a handoff for every lane ({', '.join(workers)}), then explicitly freeze.")
        decision = interrupt({"kind": "worker_handoff", "message": message})
        if decision != {"freeze": True}:
            raise ValueError("Explicit freeze required")
        return {"snapshots": runtime.freeze()}
    def candidate(state): return {"bundle": runtime.candidate(state)}
    def review(_state):
        _, digest = runtime.validate_bundle()
        if runtime.plan.get("automatic"):
            from .automatic import review_candidate
            decision = review_candidate(runtime)
        else:
            decision = interrupt({"kind": "independent_review", "bundle_sha256": digest,
                                  "bundle_path": str(runtime.directory / "review-bundle.json")})
        runtime.validate_review(decision)
        save_json(runtime.directory / "review.json", decision)
        runtime.event("review", "approved", decision["reviewer"])
        return {"review": decision}
    def approval(_state):
        _, digest = runtime.validate_bundle()
        if runtime.plan.get("automatic"):
            from .automatic import validate_automatic
            validate_automatic(runtime.plan)
            decision = {"approve": digest}  # Explicit run-level authority: feature branch only.
        else:
            decision = interrupt({"kind": "integration_approval", "bundle_sha256": digest,
                                  "message": "Approve fast-forward of source branch; no push."})
        if decision != {"approve": digest}:
            raise ValueError("Explicit exact-bundle approval required")
        return {"approved_bundle": digest}
    def integrate(state): return {"integrated_commit": runtime.integrate(state["approved_bundle"])}
    graph = StateGraph(PipelineState)
    launches = [f"launch_{node}" for node in workers]

def listed_rows(result: subprocess.CompletedProcess) -> list | None:
    """The rows of one `claude agents --json` answer, or None when it is not a listing: a nonzero exit, or output that is not a JSON list."""
    if result.returncode != 0:
        return None
    try:
        rows = json.loads(result.stdout)
    except (TypeError, ValueError):
        return None
    return rows if isinstance(rows, list) else None


class InteractiveSessions(ClaudeSessions):
    """Native Claude background sessions, not print-mode jobs or Herdr-owned agents."""

    def inventory(self) -> list[dict]:
        """`claude agents --json`. The listing only reads, so while the background service restarts (it exits nonzero,
        prints no list or hangs) it is asked again for the grace; a listing that stays unavailable is TransientInfraError.
        """
        try:
            response = run_claude([self.executable, "agents", "--json"], capture_output=True, text=True, timeout=15,
                                  retry_output=lambda result: listed_rows(result) is None)
        except subprocess.TimeoutExpired as error:
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: {error}") from error
        rows = listed_rows(response)
        if rows is None:
            # Claude Code is unavailable, which says nothing about any session.
            answer = f"exited {response.returncode}" if response.returncode else "printed no session list"
            detail = ((response.stderr or "").strip() or (response.stdout or "").strip())[-300:]
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: "
                                      f"`claude agents --json` {answer}" + (f": {detail}" if detail else ""))
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    """`--settings` for every `claude --bg` command: the auto-updater off inside the session it starts.

    The short `--bg` helper only hands the session to Claude Code's background service, which starts it with the
    service's own environment plus an allowlist of the helper's (provider, model, config, endpoint and PATH variables),
    so claude_env reaches the session only when this run happened to start the service. The helper's arguments do
    reach it, and settings given there are merged over the user's and the project's.
    """
    return ["--settings", json.dumps({"env": AUTOUPDATER_OFF})]


def wait_out_update(start, grace: float, sleep=None, retry_output=None):
    """`start()` (it runs or starts one `claude` command), repeated while a Claude Code update is in progress.

    An update replaces the installed binary: for a moment the command is missing (ENOENT), half written (ENOEXEC)
    or busy (ETXTBSY), and the exec fails before anything runs. That is repeated every 2 seconds for `grace`
    seconds, then raised as TransientInfraError. `retry_output`, when given, marks a command that only reads (the
    session inventory), so running it again is harmless: an answer it rejects (the restarting background service
    exits nonzero or lists nothing) and a timeout are repeated too, a timeout spending its own seconds of the
    grace; once the grace is spent the last answer is returned, or the timeout raised. Any other failure is raised
    at once, and a command that ran is never repeated without `retry_output`: a launch or a print job never starts twice.
    """
    sleep = sleep or time.sleep
    waited = 0.0
    while True:
        try:
            result = start()
        except OSError as error:
            if not (isinstance(error, FileNotFoundError) or error.errno in UPDATE_ERRNOS):
                raise
            if waited >= grace:
                raise TransientInfraError(f"Claude Code unavailable for {grace:g}s ({error}); an update may be replacing it") from error
        except subprocess.TimeoutExpired as error:
            waited += error.timeout
            if retry_output is None or waited >= grace:
                raise
        else:
            if retry_output is None or not retry_output(result) or waited >= grace:
                return result
        sleep(2)
        waited += 2


def run_claude(command: list[str], *, grace: float = CLAUDE_MISSING_GRACE_SECONDS, sleep=None, retry_output=None,
               **kwargs) -> subprocess.CompletedProcess:
    """`subprocess.run` for a `claude` command, with the auto-updater off, that waits out an update in progress (wait_out_update)."""
    kwargs["env"] = claude_env(kwargs.get("env"))
    return wait_out_update(lambda: subprocess.run(command, **kwargs), grace, sleep, retry_output)


def popen_claude(command: list[str], *, grace: float = CLAUDE_MISSING_GRACE_SECONDS, sleep=None, **kwargs) -> subprocess.Popen:
    """`subprocess.Popen` for a `claude` print job, like run_claude: only a failed exec is repeated, a started job never."""
    kwargs["env"] = claude_env(kwargs.get("env"))
    return wait_out_update(lambda: subprocess.Popen(command, **kwargs), grace, sleep)


